// ===== Diffusion Photos Discord — RSS (Airtable « rss photo ») → Discord =====
// ⚠️ PHASE 1 : placeholders à remplacer par tes vraies clés/IDs (voir README)
const CONFIG = {
  airtableToken: 'AIRTABLE_TOKEN_PLACEHOLDER',
  baseId: 'BASE_ID_PLACEHOLDER',            // ex. appXXXXXXXXXXXXXX (base « rss photo »)
  feedsTableId: 'FEEDS_TABLE_ID_PLACEHOLDER',   // table des flux photos
  photosTableId: 'PHOTOS_TABLE_ID_PLACEHOLDER', // table de marquage des envois
  discordWebhook: 'DISCORD_WEBHOOK_PLACEHOLDER', // webhook par défaut si un flux n'a pas de salon
  maxParFlux: 5,                             // anti-flood : 5 max par flux et par run

  // --- mapping des champs (adapte ici si les noms diffèrent) ---
  champsFlux: { nom: 'Name', url: 'URL source rss', salon: 'Salon discord' },
  champsPhotos: { lien: 'Lien', sources: 'Sources', titres: 'Titres', sommaire: 'Sommaire',
                  date: 'Date publication', salon: 'Salon Discord' },
};

const decodeEntities = (s) => (s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#0?39;|&apos;|&#39;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ').trim();

const pick = (block, tag) => {
  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'i'));
  return m ? m[1].trim() : '';
};

function imgOf(block) {
  let m = block.match(/<media:(?:content|thumbnail)[^>]*url="([^"]+)"/i);
  if (m) return m[1].trim();
  m = block.match(/<enclosure[^>]*url="([^"]+)"[^>]*type="image[^"]*"/i) ||
      block.match(/<enclosure[^>]*type="image[^"]*"[^>]*url="([^"]+)"/i);
  if (m) return m[1].trim();
  const content = pick(block, 'content:encoded') || pick(block, 'description') || pick(block, 'summary');
  m = content.match(/<img[^>]*src="([^"]+)"/i) || content.match(/<img[^>]*src='([^']+)'/i);
  return m ? m[1].trim() : '';
}

function parseFeed(xml) {
  const items = [];
  const blocks = [...xml.matchAll(/<(?:item|entry)[\s>][\s\S]*?<\/(?:item|entry)>/gi)];
  for (const b of blocks) {
    const block = b[0];
    const title = decodeEntities(pick(block, 'title'));
    let link = pick(block, 'link');
    if (!link) { const lm = block.match(/<link[^>]*href="([^"]+)"/i); if (lm) link = lm[1].trim(); }
    if (!link) continue;
    const description = decodeEntities(pick(block, 'description') || pick(block, 'summary') || pick(block, 'content'));
    const pub = pick(block, 'pubDate') || pick(block, 'published') || pick(block, 'updated') || '';
    let isoDate = pub ? new Date(pub).toISOString() : new Date().toISOString();
    if (isNaN(new Date(isoDate).getTime())) isoDate = new Date().toISOString();
    items.push({ title, link, description, isoDate, image: imgOf(block) });
  }
  return items;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// --- exécution ---
const F = CONFIG.champsFlux, P = CONFIG.champsPhotos;
const H = { Authorization: `Bearer ${CONFIG.airtableToken}`, 'Content-Type': 'application/json' };
const base = `https://api.airtable.com/v0/${CONFIG.baseId}`;
const rapport = [];
let feeds = [], offset;
do {
  const r = await this.helpers.httpRequest({ url: `${base}/${CONFIG.feedsTableId}`, headers: H, json: true });
  feeds = feeds.concat((r.records || []).map((rec) => ({
    nom: rec.fields[F.nom] || 'flux sans nom',
    url: rec.fields[F.url],
    salon: rec.fields[F.salon] || CONFIG.discordWebhook || '',
  })));
  offset = r.offset;
  if (offset) await sleep(250);
} while (offset);

for (const feed of feeds) {
  const entree = { feed: feed.nom, trouves: 0, envoyes: 0, marques: 0, dejaVus: 0, erreurs: [] };
  try {
    const raw = await this.helpers.httpRequest({
      url: feed.url, method: 'GET', headers: { 'User-Agent': 'n8n-rss-discord' }, json: false,
    });
    const text = typeof raw === 'string' ? raw : (raw && raw.body ? String(raw.body) : String(raw));
    const articles = parseFeed(text);
    entree.trouves = articles.length;
    articles.sort((a, b) => new Date(b.isoDate) - new Date(a.isoDate));
    let deja = 0, envoyes = 0;
    for (const art of articles) {
      if (envoyes >= CONFIG.maxParFlux) { entree.erreurs.push(`cap ${CONFIG.maxParFlux} atteinte, suite au prochain run`); break; }
      const f = `{${P.lien}}='${art.link.replace(/'/g, "\\'")}'`;
      const chk = await this.helpers.httpRequest({
        url: `${base}/${CONFIG.photosTableId}`, headers: H, json: true,
        qs: { filterByFormula: f, maxRecords: 1 },
      });
      await sleep(250);
      if ((chk.records || []).length > 0) { deja++; continue; }

      // image : du flux, sinon og:image de la page
      let image = art.image;
      if (!image && feed.salon) {
        try {
          const page = await this.helpers.httpRequest({
            url: art.link, method: 'GET', headers: { 'User-Agent': 'n8n-rss-discord' }, json: false,
          });
          const html = typeof page === 'string' ? page : (page && page.body ? String(page.body) : String(page));
          const m = html.match(/property=["']og:image["'][^>]*content=["']([^"']+)["']/i) ||
                    html.match(/content=["']([^"']+)["'][^>]*property=["']og:image["']/i) ||
                    html.match(/name=["']twitter:image["'][^>]*content=["']([^"']+)["']/i);
          if (m && m[1]) image = m[1].trim();
          await sleep(400);
        } catch { /* pas d'image → pas grave */ }
      }

      if (feed.salon) {
        const embed = {
          title: art.title.slice(0, 250) || '(sans titre)',
          url: art.link,
          description: art.description.slice(0, 350) || '',
          color: 10181046,   // violet : distingue les photos des actus (vert)
          footer: { text: feed.nom },
          timestamp: art.isoDate,
        };
        if (image) embed.image = { url: image };
        await this.helpers.httpRequest({
          url: feed.salon, method: 'POST', json: true,
          headers: { 'Content-Type': 'application/json' },
          body: { embeds: [embed] },
        });
        await sleep(400);
        envoyes++;
      }
      await this.helpers.httpRequest({
        url: `${base}/${CONFIG.photosTableId}`, method: 'POST', headers: H, json: true,
        body: { records: [{ fields: {
          [P.lien]: art.link,
          [P.sources]: feed.nom,
          [P.titres]: (art.title || '').slice(0, 255),
          [P.sommaire]: art.description.slice(0, 255),
          [P.date]: art.isoDate.slice(0, 10),
          [P.salon]: feed.salon || '',
        } }] },
      });
      await sleep(250);
      entree.marques++;
    }
    entree.envoyes = envoyes;
    entree.dejaVus = deja;
  } catch (e) {
    entree.erreurs.push(String(e.message || e));
  }
  rapport.push(entree);
  await sleep(250);
}
return [{ json: { workflow: 'Diffusion Photos Discord', flux: feeds.length, rapport } }];
